'use client';

import {
  MobileNav,
  MobileNavLinks,
} from '@/registry/ndeko/components/navbar/_parts/mobile-nav';
import {
  NavLinks,
  type NavLinkItem,
} from '@/registry/ndeko/components/navbar/_parts/nav-links';
import { NotificationMenu } from '@/registry/ndeko/components/navbar/_parts/notification-menu';
import { TeamSwitcher } from '@/registry/ndeko/components/navbar/_parts/team-switcher';
import { useActiveLink } from '@/registry/ndeko/components/navbar/_parts/use-active-link';
import { UserMenu } from '@/registry/ndeko/components/navbar/_parts/user-menu';
import {
  CompassIcon,
  FeatherIcon,
  HouseIcon,
  PlusIcon,
  SearchIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

const TEAMS = ['Acme Inc.', 'Lumen Labs', 'Junon'];

const LINKS: NavLinkItem[] = [
  { href: '#', label: 'Dashboard', icon: HouseIcon },
  { href: '#', label: 'Explore', icon: CompassIcon },
  { href: '#', label: 'Write', icon: FeatherIcon },
  { href: '#', label: 'Search', icon: SearchIcon },
];

export default function Navbar14() {
  const { activeLabel, navigate } = useActiveLink();

  return (
    <header className='hairline-b border-border px-4 md:px-6'>
      <div className='flex h-16 items-center justify-between gap-4'>
        <div className='flex flex-1 items-center gap-2'>
          <MobileNav className='w-48'>
            <MobileNavLinks
              links={LINKS}
              activeLabel={activeLabel}
              onNavigate={navigate}
              showsIcons
            />
          </MobileNav>
          <TeamSwitcher teams={TEAMS} defaultTeam={TEAMS[0]} />
        </div>
        <NavLinks
          links={LINKS}
          activeLabel={activeLabel}
          onNavigate={navigate}
          display='icon'
          className='max-md:hidden'
        />
        <div className='flex flex-1 items-center justify-end gap-4'>
          <Button className='max-sm:aspect-square max-sm:px-0'>
            <PlusIcon className='opacity-60' />
            <span className='max-sm:sr-only'>Post</span>
          </Button>
          <NotificationMenu />
          <UserMenu />
        </div>
      </div>
    </header>
  );
}

'use client';

import { createContext, useContext, useState } from 'react';

import {
  isPlaceholderHref,
  NavLinkIcon,
  type NavLinkItem,
} from '@/registry/ndeko/components/navbar/_parts/nav-links';
import {
  MENU_ITEM,
  MENU_LABEL,
  MENU_SEPARATOR,
} from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

const CloseMenuContext = createContext<() => void>(() => undefined);

const BAR =
  'origin-center transition-[translate,rotate] duration-300 ease-(--ease-out-strong)';

const LINK_ROW = cn(
  MENU_ITEM,
  'text-muted-foreground cursor-pointer transition-colors duration-150',
  'hover:bg-foreground/5 hover:text-foreground focus-visible:bg-foreground/5 focus-visible:text-foreground',
  'data-active:bg-foreground/[0.06] data-active:text-foreground dark:data-active:bg-foreground/10'
);

function menuLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Close menu';
  }
  return 'Open menu';
}

function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

function MenuToggleIcon() {
  return (
    <svg
      viewBox='0 0 24 24'
      fill='none'
      stroke='currentColor'
      strokeWidth='1.75'
      strokeLinecap='round'
      strokeLinejoin='round'
      aria-hidden='true'
      className='pointer-events-none size-4'
    >
      <path
        d='M4 12H20'
        className={cn(
          BAR,
          '-translate-y-[7px] group-aria-expanded/button:translate-y-0 group-aria-expanded/button:rotate-[315deg]'
        )}
      />
      <path
        d='M4 12H20'
        className={cn(BAR, 'group-aria-expanded/button:rotate-45')}
      />
      <path
        d='M4 12H20'
        className={cn(
          BAR,
          'translate-y-[7px] group-aria-expanded/button:translate-y-0 group-aria-expanded/button:rotate-[135deg]'
        )}
      />
    </svg>
  );
}

type MobileNavProps = {
  children: React.ReactNode;
  className?: string;
};

function MobileNav({ children, className }: MobileNavProps) {
  const [isOpen, setIsOpen] = useState(false);

  function changeOpen(open: boolean) {
    setIsOpen(open);
  }

  function closeMenu() {
    setIsOpen(false);
  }

  return (
    <Popover open={isOpen} onOpenChange={changeOpen}>
      <PopoverTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            aria-label={menuLabelOf(isOpen)}
            className='md:hidden'
          />
        }
      >
        <MenuToggleIcon />
      </PopoverTrigger>
      <PopoverContent
        align='start'
        className={cn('w-44 p-1 md:hidden', className)}
      >
        <nav aria-label='Main'>
          <CloseMenuContext.Provider value={closeMenu}>
            {children}
          </CloseMenuContext.Provider>
        </nav>
      </PopoverContent>
    </Popover>
  );
}

type MobileNavLinkProps = {
  href: string;
  isActive?: boolean;
  onClick?: () => void;
  className?: string;
  children: React.ReactNode;
};

function MobileNavLink({
  href,
  isActive = false,
  onClick,
  className,
  children,
}: MobileNavLinkProps) {
  const closeMenu = useContext(CloseMenuContext);

  function follow(event: React.MouseEvent<HTMLAnchorElement>) {
    if (isPlaceholderHref(href)) {
      event.preventDefault();
    }
    onClick?.();
    closeMenu();
  }

  return (
    <a
      href={href}
      aria-current={ariaCurrentOf(isActive)}
      data-active={isActive || undefined}
      onClick={follow}
      className={cn(LINK_ROW, className)}
    >
      {children}
    </a>
  );
}

type MobileNavLinksProps = {
  links: NavLinkItem[];
  activeLabel?: string;
  onNavigate?: (label: string) => void;
  showsIcons?: boolean;
};

function MobileNavLinks({
  links,
  activeLabel,
  onNavigate,
  showsIcons = false,
}: MobileNavLinksProps) {
  return (
    <ul className='flex flex-col'>
      {links.map((link) => (
        <li key={link.label}>
          <MobileNavLink
            href={link.href}
            isActive={link.label === activeLabel}
            onClick={() => onNavigate?.(link.label)}
          >
            {showsIcons && <NavLinkIcon icon={link.icon} />}
            {link.label}
          </MobileNavLink>
        </li>
      ))}
    </ul>
  );
}

function MobileNavHeading({ children }: { children: React.ReactNode }) {
  return <div className={MENU_LABEL}>{children}</div>;
}

function MobileNavSeparator() {
  return (
    <div
      role='separator'
      aria-orientation='horizontal'
      className={MENU_SEPARATOR}
    />
  );
}

export {
  MobileNav,
  MobileNavHeading,
  MobileNavLink,
  MobileNavLinks,
  MobileNavSeparator,
};

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };
const EXIT_TRANSITION: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const LABEL_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)', transition: EXIT_TRANSITION },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT_TRANSITION },
};

function labelVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return LABEL_VARIANTS;
}

type MorphingLabelProps = {
  value: string;
  className?: string;
  children: React.ReactNode;
};

function MorphingLabel({ value, className, children }: MorphingLabelProps) {
  const shouldReduceMotion = useReducedMotion();
  const labelVariants = labelVariantsOf(shouldReduceMotion);

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={value}
          className={cn('flex whitespace-nowrap', className)}
          variants={labelVariants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

export { MorphingLabel };

'use client';

import {
  LayoutGroup,
  motion,
  type Transition,
  useReducedMotion,
} from 'motion/react';
import { useId } from 'react';

import type { Icon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  NavigationMenu,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
} from '@/registry/ndeko/ui/navigation-menu';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

type NavLinkItem = { label: string; href: string; icon?: Icon };

type NavIndicator = 'pill' | 'underline';

type NavLinkDisplay = 'label' | 'icon-label' | 'icon';

const SLIDE_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};
const INSTANT_TRANSITION: Transition = { duration: 0 };

const LINK_BASE =
  'relative flex-row items-center gap-2 py-0 font-medium text-muted-foreground hover:bg-transparent hover:text-foreground data-active:bg-transparent data-active:text-foreground';

const LINK_SHAPE: Record<NavIndicator, string> = {
  pill: 'h-8 rounded-md px-3',
  underline: 'h-full rounded-sm px-0.5',
};

const ICON_ONLY_SHAPE = 'size-8 justify-center px-0';

const LIST_CLASS: Record<NavIndicator, string> = {
  pill: 'gap-1',
  underline: 'h-full gap-6',
};

const ITEM_CLASS: Record<NavIndicator, string> = {
  pill: '',
  underline: 'h-full',
};

const INDICATOR_CLASS: Record<NavIndicator, string> = {
  pill: 'absolute inset-0 rounded-md bg-foreground/[0.06] dark:bg-foreground/10',
  underline: 'absolute inset-x-0 bottom-0 h-0.5 rounded-full bg-primary',
};

function slideTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT_TRANSITION;
  }
  return SLIDE_TRANSITION;
}

function isPlaceholderHref(href: string) {
  return href === '#';
}

function NavLinkIcon({ icon: LinkIcon }: { icon?: Icon }) {
  if (!LinkIcon) {
    return null;
  }
  return <LinkIcon className='size-4' />;
}

type NavLinksItemProps = {
  link: NavLinkItem;
  isActive: boolean;
  indicator: NavIndicator;
  display: NavLinkDisplay;
  transition: Transition;
  onFollow: (
    event: React.MouseEvent<HTMLAnchorElement>,
    link: NavLinkItem
  ) => void;
};

function NavLinksItem({
  link,
  isActive,
  indicator,
  display,
  transition,
  onFollow,
}: NavLinksItemProps) {
  const isIconOnly = display === 'icon';
  const showsIcon = display !== 'label';
  const linkClassName = cn(
    LINK_BASE,
    LINK_SHAPE[indicator],
    isIconOnly && ICON_ONLY_SHAPE
  );

  function follow(event: React.MouseEvent<HTMLAnchorElement>) {
    onFollow(event, link);
  }

  const content = (
    <>
      {isActive && (
        <motion.span
          layoutId='active-link-indicator'
          transition={transition}
          className={INDICATOR_CLASS[indicator]}
        />
      )}
      <span className='relative flex items-center gap-2'>
        {showsIcon && <NavLinkIcon icon={link.icon} />}
        {isIconOnly && <span className='sr-only'>{link.label}</span>}
        {!isIconOnly && link.label}
      </span>
    </>
  );

  if (isIconOnly) {
    return (
      <NavigationMenuItem className={ITEM_CLASS[indicator]}>
        <Tooltip>
          <TooltipTrigger
            render={
              <NavigationMenuLink
                href={link.href}
                active={isActive}
                onClick={follow}
                className={linkClassName}
              />
            }
          >
            {content}
          </TooltipTrigger>
          <TooltipContent side='bottom'>{link.label}</TooltipContent>
        </Tooltip>
      </NavigationMenuItem>
    );
  }

  return (
    <NavigationMenuItem className={ITEM_CLASS[indicator]}>
      <NavigationMenuLink
        href={link.href}
        active={isActive}
        onClick={follow}
        className={linkClassName}
      >
        {content}
      </NavigationMenuLink>
    </NavigationMenuItem>
  );
}

type NavLinksProps = {
  links: NavLinkItem[];
  activeLabel?: string;
  onNavigate: (label: string) => void;
  indicator?: NavIndicator;
  display?: NavLinkDisplay;
  className?: string;
};

function NavLinks({
  links,
  activeLabel,
  onNavigate,
  indicator = 'pill',
  display = 'label',
  className,
}: NavLinksProps) {
  const groupId = useId();
  const shouldReduceMotion = useReducedMotion();
  const transition = slideTransitionOf(shouldReduceMotion);
  const isUnderline = indicator === 'underline';

  function followLink(
    event: React.MouseEvent<HTMLAnchorElement>,
    link: NavLinkItem
  ) {
    if (isPlaceholderHref(link.href)) {
      event.preventDefault();
    }
    onNavigate(link.label);
  }

  return (
    <LayoutGroup id={groupId}>
      <TooltipProvider>
        <NavigationMenu
          aria-label='Main'
          className={cn(isUnderline && 'h-full', className)}
        >
          <NavigationMenuList className={LIST_CLASS[indicator]}>
            {links.map((link) => (
              <NavLinksItem
                key={link.label}
                link={link}
                isActive={link.label === activeLabel}
                indicator={indicator}
                display={display}
                transition={transition}
                onFollow={followLink}
              />
            ))}
          </NavigationMenuList>
        </NavigationMenu>
      </TooltipProvider>
    </LayoutGroup>
  );
}

export {
  NavLinkIcon,
  NavLinks,
  isPlaceholderHref,
  type NavIndicator,
  type NavLinkDisplay,
  type NavLinkItem,
};

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useState } from 'react';

import { BellIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Popover,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

type Notification = {
  id: number;
  user: string;
  action: string;
  target: string;
  timestamp: string;
  isUnread: boolean;
};

const INITIAL_NOTIFICATIONS: Notification[] = [
  {
    id: 1,
    user: 'Chris Tompson',
    action: 'requested review on',
    target: 'PR #42: Feature implementation',
    timestamp: '15 minutes ago',
    isUnread: true,
  },
  {
    id: 2,
    user: 'Emma Davis',
    action: 'shared',
    target: 'New component library',
    timestamp: '45 minutes ago',
    isUnread: true,
  },
  {
    id: 3,
    user: 'James Wilson',
    action: 'assigned you to',
    target: 'API integration task',
    timestamp: '4 hours ago',
    isUnread: false,
  },
  {
    id: 4,
    user: 'Alex Morgan',
    action: 'replied to your comment in',
    target: 'Authentication flow',
    timestamp: '12 hours ago',
    isUnread: false,
  },
  {
    id: 5,
    user: 'Sarah Chen',
    action: 'commented on',
    target: 'Dashboard redesign',
    timestamp: '2 days ago',
    isUnread: false,
  },
  {
    id: 6,
    user: 'Noah Patel',
    action: 'mentioned you in',
    target: 'Launch page open graph image',
    timestamp: '2 weeks ago',
    isUnread: false,
  },
];

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };
const EXIT_TRANSITION: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const POP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: {
    opacity: 0,
    scale: 0.6,
    filter: 'blur(2px)',
    transition: EXIT_TRANSITION,
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT_TRANSITION },
};

function popVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return POP_VARIANTS;
}

function notificationsLabelOf(unreadCount: number) {
  if (unreadCount === 0) {
    return 'Open notifications';
  }
  if (unreadCount === 1) {
    return 'Open notifications, 1 unread';
  }
  return `Open notifications, ${unreadCount} unread`;
}

function markAsRead(notification: Notification) {
  return { ...notification, isUnread: false };
}

function NotificationMenu() {
  const [notifications, setNotifications] = useState(INITIAL_NOTIFICATIONS);
  const shouldReduceMotion = useReducedMotion();
  const popVariants = popVariantsOf(shouldReduceMotion);
  const unreadCount = notifications.filter(
    (notification) => notification.isUnread
  ).length;
  const hasUnread = unreadCount > 0;

  function markAllAsRead() {
    setNotifications((current) => current.map(markAsRead));
  }

  function markOneAsRead(id: number) {
    setNotifications((current) =>
      current.map((notification) => {
        if (notification.id !== id) {
          return notification;
        }
        return markAsRead(notification);
      })
    );
  }

  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            aria-label={notificationsLabelOf(unreadCount)}
            className='text-muted-foreground'
          />
        }
      >
        <BellIcon />
        <AnimatePresence initial={false}>
          {hasUnread && (
            <motion.span
              key='unread-dot'
              aria-hidden='true'
              className='bg-primary absolute top-1.5 right-1.5 size-1.5 rounded-full'
              variants={popVariants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
            />
          )}
        </AnimatePresence>
      </PopoverTrigger>
      <PopoverContent align='end' className='w-80 p-1'>
        <div className='flex items-baseline justify-between gap-4 px-3 py-2'>
          <PopoverTitle>Notifications</PopoverTitle>
          <Button
            variant='link'
            size='sm'
            onClick={markAllAsRead}
            disabled={!hasUnread}
            focusableWhenDisabled
            className='h-auto p-0 text-xs'
          >
            Mark all as read
          </Button>
        </div>
        <ul className='flex flex-col'>
          {notifications.map((notification) => (
            <li
              key={notification.id}
              className='has-focus-visible:bg-foreground/5 hover:bg-foreground/5 relative flex items-start gap-3 rounded-md px-3 py-2 transition-colors duration-150'
            >
              <div className='flex min-w-0 flex-1 flex-col gap-1'>
                <button
                  type='button'
                  onClick={() => markOneAsRead(notification.id)}
                  className='text-muted-foreground text-left outline-none after:absolute after:inset-0'
                >
                  <span className='text-foreground font-medium'>
                    {notification.user}
                  </span>{' '}
                  {notification.action}{' '}
                  <span className='text-foreground font-medium'>
                    {notification.target}
                  </span>
                  .
                </button>
                <span className='text-muted-foreground text-xs'>
                  {notification.timestamp}
                </span>
              </div>
              <span className='flex size-1.5 shrink-0 self-center'>
                <AnimatePresence initial={false}>
                  {notification.isUnread && (
                    <motion.span
                      key='unread'
                      className='bg-primary size-1.5 rounded-full'
                      variants={popVariants}
                      initial='enter'
                      animate='visible'
                      exit='exit'
                      transition={SWAP_TRANSITION}
                    >
                      <span className='sr-only'>Unread</span>
                    </motion.span>
                  )}
                </AnimatePresence>
              </span>
            </li>
          ))}
        </ul>
      </PopoverContent>
    </Popover>
  );
}

export { NotificationMenu };

'use client';

import { useState } from 'react';

import { MorphingLabel } from '@/registry/ndeko/components/navbar/_parts/morphing-label';
import { ChevronsUpDownIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

const GEM_STYLE = { '--gem': 'var(--primary)' } as React.CSSProperties;

function initialOf(team: string) {
  const firstLetter = team.charAt(0);
  return firstLetter.toUpperCase();
}

function TeamMark({ team }: { team: string }) {
  return (
    <span
      aria-hidden='true'
      style={GEM_STYLE}
      className='gem-plate flex size-6 shrink-0 items-center justify-center rounded-md text-xs font-semibold'
    >
      {initialOf(team)}
    </span>
  );
}

type TeamSwitcherProps = {
  teams: string[];
  defaultTeam: string;
};

function TeamSwitcher({ teams, defaultTeam }: TeamSwitcherProps) {
  const [selectedTeam, setSelectedTeam] = useState(defaultTeam);

  function selectTeam(team: string) {
    setSelectedTeam(team);
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={<Button variant='ghost' className='gap-2 px-1.5' />}
      >
        <TeamMark team={selectedTeam} />
        <MorphingLabel value={selectedTeam}>{selectedTeam}</MorphingLabel>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5' />
      </DropdownMenuTrigger>
      <DropdownMenuContent>
        <DropdownMenuRadioGroup value={selectedTeam} onValueChange={selectTeam}>
          {teams.map((team) => (
            <DropdownMenuRadioItem key={team} value={team} closeOnClick>
              <TeamMark team={team} />
              {team}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export { TeamSwitcher };

import { useState } from 'react';

function useActiveLink(initialLabel?: string) {
  const [activeLabel, setActiveLabel] = useState(initialLabel);

  function navigate(label: string) {
    setActiveLabel(label);
  }

  return { activeLabel, navigate };
}

export { useActiveLink };
